qs_goal_teach() {
  case "$1" in
    'look')
      q_say 'ls -l shows each file'\''s permissions at the start of its line: r (read), w (write) and x (execute, meaning run), three times over: for you, your group and everyone. The kettle-bot has no x.'
      ;;
    'run')
      q_say 'chmod changes permissions. chmod +x kettle-bot adds the x, so ./kettle-bot can run. (The ./ means "this one, right here": the shell doesn'\''t look in the current folder for programs on its own.)'
      ;;
    'power')
      q_say 'POWER=on makes a shell variable. export POWER shares it with the programs you run (an environment variable). Do both at once with export POWER=on, then run ./kettle-bot.'
      ;;
    'path')
      q_say 'PATH is the list of folders the shell searches when you type a program'\''s name, separated by colons. export PATH="$PATH:$HOME/workshop/tools" adds the tools folder to the end. Now oil works from anywhere, with no ./ in front.'
      ;;
    'tick')
      q_say 'alias tick='\''./clock --wind --twice'\'' makes tick stand for the whole command. Then just type tick.'
      ;;
    'settings')
      q_say 'Running ./settings starts a new shell, sets GEAR_SIZE there, and throws it all away when it ends. source settings runs the same lines in YOUR shell, so what they set stays.'
      ;;
    'bell')
      q_say 'Every program ends with an exit code: 0 means it worked, anything else means it didn'\''t (echo $? shows the last one). && runs the next command only if the first one worked: ./gearbox && ./bell.'
      ;;
  esac
}

