qs_goal_solution() {
  case "$1" in
    'look')
      printf '%s\n' 'ls -l'
      ;;
    'run')
      printf '%s\n' 'chmod +x kettle-bot'
      ;;
    'power')
      printf '%s\n' 'export POWER=on'
      printf '%s\n' './kettle-bot'
      ;;
    'path')
      printf '%s\n' 'export PATH="$PATH:$HOME/workshop/tools"'
      printf '%s\n' 'oil gears'
      ;;
    'tick')
      printf '%s\n' 'alias tick='\''./clock --wind --twice'\'''
      printf '%s\n' 'tick'
      ;;
    'settings')
      printf '%s\n' 'source settings'
      ;;
    'bell')
      printf '%s\n' './gearbox && ./bell'
      ;;
  esac
}

