qs_object() {
  QS_OBJECT="$1"
  shift
  case "$QS_OBJECT" in
    'kettle-bot')
      if { q_env 'POWER' equals 'on'; }; then
        q_ran_mark 'kettle-bot'
        q_say 'The kettle-bot whirs, hisses, and pours you a perfect cup of tea.'
        q_flag_set 'tea'
        return 0
      fi
      q_say 'NO POWER
      (The kettle-bot reads the environment variable POWER. If you set POWER=on but did not export it, programs can'\''t see it yet.)'
      return 1
      ;;
    'tools/oil')
      if [ $# -eq 1 ] && [ "${1}" = 'gears' ]; then
        q_ran_mark 'tools/oil'
        q_say 'Glug, glug. The gears are oiled and shining.'
        q_flag_set 'oiled'
        return 0
      fi
      q_say 'oil: what should I oil? Try:  oil gears'
      return 1
      ;;
    'clock')
      if [ $# -eq 2 ] && [ "${1}" = '--wind' ] && [ "${2}" = '--twice' ]; then
        q_ran_mark 'clock'
        q_say 'Tick, tock. Tick, tock. The clock is wound for the day.'
        q_flag_set 'wound'
        return 0
      fi
      if [ $# -eq 1 ] && [ "${1}" = '--secret' ]; then
        q_ran_mark 'clock'
        q_say 'A little drawer springs open in the clock face. Inside, rolled up: a blueprint. You put it on the bench as blueprint.txt.'
        q_write 'blueprint.txt' 'BLUEPRINT: the Clockwork Owl. Ada'\''s next invention.
        A clock that hoots on the hour.
        '
        return 0
      fi
      if [ $# -eq 1 ] && [ "${1}" = '--wind' ]; then
        q_ran_mark 'clock'
        q_say 'Tick, tock. That'\''s one wind. It needs two: --wind --twice.'
        return 0
      fi
      q_say 'The clock wants options. Read it first: cat clock'
      return 1
      ;;
    'gearbox')
      if { q_env 'GEAR_SIZE' equals '7'; }; then
        q_ran_mark 'gearbox'
        q_say 'Clunk. Whirr. The gearbox turns, smooth as silk.'
        q_flag_set 'geared'
        return 0
      fi
      q_say 'The gearbox grinds and stops: GEAR_SIZE is not set. (Load the settings into this shell: source settings.)'
      return 1
      ;;
    'bell')
      if [ $# -eq 1 ] && [ "${1}" = '--three-times' ] && { q_flag 'geared'; }; then
        q_ran_mark 'bell'
        q_say 'DONG. DONG. DONG. The bell rings out over the town, and on the third ring something small and shiny falls from the tower and rolls to your feet.'
        q_flag_set 'rung'
        q_flag_set 'lucky'
        return 0
      fi
      if { q_flag 'geared'; }; then
        q_ran_mark 'bell'
        q_say 'DONG. The bell rings out over the whole town. Noon, right on time.'
        q_flag_set 'rung'
        return 0
      fi
      q_say 'The bell rope hangs slack: the gearbox isn'\''t turning, so nothing pulls it.'
      return 1
      ;;
  esac
  return 1
}
